/**
 * Python-flavoured exception objects.
 *
 * The original script lets exceptions escape to the interpreter, which prints a
 * traceback to stderr and exits with status 1.  These classes carry the extra
 * metadata (Python exception type name, the frames the exception travelled
 * through) needed to reproduce that shape.
 */

export class PyError extends Error {
  /**
   * @param {string} pyType Python class name, e.g. "ValueError".
   * @param {string} pyMessage Text that follows the class name in a traceback.
   */
  constructor(pyType, pyMessage) {
    super(`${pyType}: ${pyMessage}`);
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    /** @type {{file: string, line: number, name: string}[]} innermost last */
    this.pyFrames = [];
  }

  /** Record a frame the exception propagated through (innermost first). */
  addFrame(file, line, name) {
    this.pyFrames.unshift({ file, line, name });
    return this;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyUnicodeEncodeError extends PyError {
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

/** Render a `PyError` the way CPython renders an unhandled exception. */
export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of err.pyFrames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }
  lines.push(`${err.pyType}: ${err.pyMessage}`);
  return lines.join('\n') + '\n';
}

