/**
 * Byte-sequence primitives.
 *
 * A Python `bytes` value is modelled as a plain JavaScript array of integers in
 * the range 0..255.  Every helper here takes and returns such arrays, so the
 * whole pipeline stays on ordinary arrays and numbers.
 */

import { PyUnicodeEncodeError } from './errors.mjs';

/** ASCII whitespace stripped by `bytes.rstrip()` with no argument. */
const ASCII_WHITESPACE = [0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c];

/** Escape a code point the way CPython names it in codec error messages. */
function codePointName(cp) {
  if (cp > 0xffff) return `\\U${cp.toString(16).padStart(8, '0')}`;
  if (cp > 0xff) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\x${cp.toString(16).padStart(2, '0')}`;
}

/**
 * Walk a JS string as Python walks a `str`: one code point per step, with
 * surrogate pairs joined and lone surrogates reported by position.
 */
function codePoints(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff && i + 1 < text.length) {
      const low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        out.push({ cp: (unit - 0xd800) * 0x400 + (low - 0xdc00) + 0x10000, index: out.length });
        i += 1;
        continue;
      }
    }
    out.push({ cp: unit, index: out.length });
  }
  return out;
}

/** `str.encode()` — the UTF-8 default codec. */
export function utf8Encode(text) {
  const out = [];
  for (const { cp, index } of codePoints(text)) {
    if (cp >= 0xd800 && cp <= 0xdfff) {
      throw new PyUnicodeEncodeError(
        `'utf-8' codec can't encode character '${codePointName(cp)}' in position ` +
          `${index}: surrogates not allowed`,
      );
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/** `str.encode('ascii')` — used by base58's input scrubber. */
export function asciiEncode(text) {
  const out = [];
  for (const { cp, index } of codePoints(text)) {
    if (cp > 0x7f) {
      throw new PyUnicodeEncodeError(
        `'ascii' codec can't encode character '${codePointName(cp)}' in position ` +
          `${index}: ordinal not in range(128)`,
      );
    }
    out.push(cp);
  }
  return out;
}

/** `bytes.rstrip()` with no argument: drop trailing ASCII whitespace. */
export function rstripWhitespace(bytes) {
  let end = bytes.length;
  while (end > 0 && ASCII_WHITESPACE.includes(bytes[end - 1])) end -= 1;
  return bytes.slice(0, end);
}

/** `bytes.lstrip(single_byte)`: drop every leading occurrence of one byte. */
export function lstripByte(bytes, byte) {
  let start = 0;
  while (start < bytes.length && bytes[start] === byte) start += 1;
  return bytes.slice(start);
}

/** A run of `count` copies of one byte, as `alphabet[0:1] * n` produces. */
export function repeatByte(byte, count) {
  const out = [];
  for (let i = 0; i < count; i += 1) out.push(byte);
  return out;
}

/** Compare two byte sequences for equality (base58's checksum test). */
export function bytesEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

