/**
 * Arbitrary-precision integer helpers with Python's arithmetic semantics.
 *
 * base58 converts between byte strings and unbounded integers, so `BigInt` does
 * the heavy lifting.  The one real difference from JavaScript is division:
 * Python's `divmod` floors, JavaScript's `/` truncates toward zero.
 */

/**
 * `divmod(a, b)` — quotient floored toward negative infinity, remainder taking
 * the sign of the divisor.  `b58encode_int` relies on this for the digit loop.
 */
export function pyDivMod(a, b) {
  let quotient = a / b;
  let remainder = a % b;
  if (remainder !== 0n && remainder < 0n !== b < 0n) {
    quotient -= 1n;
    remainder += b;
  }
  return [quotient, remainder];
}

/** `int.from_bytes(v, byteorder='big')`. */
export function bytesToInt(bytes) {
  let value = 0n;
  for (const byte of bytes) value = (value << 8n) | BigInt(byte);
  return value;
}

/** `int(text)` — Python's decimal parser, including sign and `_` separators. */
export function pyParseInt(text) {
  // Python strips surrounding whitespace before parsing.
  const trimmed = text.replace(/^[\s ]+|[\s ]+$/g, '');
  // Sign, then digit groups separated by single underscores.
  if (!/^[+-]?\d+(_\d+)*$/.test(trimmed)) return null;
  const negative = trimmed.startsWith('-');
  const digits = trimmed.replace(/^[+-]/, '').replace(/_/g, '');
  const value = BigInt(digits);
  return negative ? -value : value;
}

