/**
 * Re-implementation of the `base58` Python package's public interface.
 *
 * Derived from observed behaviour only.  The notable quirks reproduced here:
 *
 *  - Decoding right-strips ASCII whitespace when the alphabet has no space in
 *    it, so `b58decode('     ')` is `b''` and `b58decode('ab\n')` decodes `ab`.
 *    Leading or interior whitespace is *not* stripped and raises instead.
 *  - Leading `1`s in the input map to leading NUL bytes in the output, and
 *    leading NUL bytes in the input map back to leading `1`s.
 *  - `b58encode_int(0)` is `b'1'`, but the digit run inside `b58encode` starts
 *    from `default_one=False`, so encoding `b''` yields `b''`.
 *  - The checksum is the first 4 bytes of a doubled SHA-256.
 */

import { PyValueError } from './errors.mjs';
import {
  asciiEncode,
  bytesEqual,
  lstripByte,
  repeatByte,
  rstripWhitespace,
} from './bytes.mjs';
import { bytesToInt, pyDivMod } from './bignum.mjs';
import { charRepr } from './pyrepr.mjs';
import { sha256 } from './sha256.mjs';

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
