export function b58encodeInt(value, { defaultOne = true, alphabet = BITCOIN_ALPHABET } = {}) {
  const digits = alphabetBytes(alphabet);
  const base = BigInt(digits.length);

  if (value === 0n && defaultOne) return [digits[0]];

  const out = [];
  let remaining = value;
  // Mirrors Python's `while i:` — a negative input never reaches zero here.
  while (remaining !== 0n) {
    const [quotient, index] = pyDivMod(remaining, base);
