/**
 * A small `argparse.ArgumentParser` clone covering what this script uses:
 * long-only optional arguments, `type=str` / `type=int`, `required=True`,
 * automatic `-h/--help`, and argparse's exact usage/error/help text.
 *
 * Exit codes match CPython: 0 after `--help`, 2 for any parse error.
 */

import { pyParseInt } from './bignum.mjs';

/** argparse treats `-1`, `-.5` etc. as values rather than option strings. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOptionString(token) {
  if (token.length === 0) return false;
  if (token[0] !== '-') return false;
  if (token === '-' || token === '--') return true;
  // No option in this parser looks like a negative number, so those are values.
  if (NEGATIVE_NUMBER.test(token)) return false;
  // A leading dash followed by a space is treated as a positional value.
  if (token.includes(' ')) return false;
  return true;
}

class Action {
  constructor(flag, { type = 'str', required = false, dest = null }) {
    this.flag = flag;
    this.type = type;
    this.required = required;
    this.dest = dest ?? flag.replace(/^--?/, '').replace(/-/g, '_');
    this.metavar = this.dest.toUpperCase();
  }

  /** How the option shows up in the usage line: `--a A`. */
  formatUsage() {
    return `${this.flag} ${this.metavar}`;
  }

  /** How it shows up in the options list — identical here, but kept separate. */
  formatInvocation() {
    return `${this.flag} ${this.metavar}`;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.helpFlags = new Set(['-h', '--help']);
  }

  addArgument(flag, options = {}) {
    const action = new Action(flag, options);
    this.actions.push(action);
    return action;
  }

  formatUsage() {
    const parts = ['[-h]', ...this.actions.map((action) => action.formatUsage())];
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  /**
   * Reproduces argparse's HelpFormatter column maths: invocations are indented
   * two spaces, and the help column sits at `min(maxLen + 2 + 2, 24)`.
   */
  formatHelp() {
    const invocations = ['-h, --help', ...this.actions.map((a) => a.formatInvocation())];
    const maxLength = Math.max(...invocations.map((text) => text.length)) + 2;
    const helpPosition = Math.min(maxLength + 2, 24);
    const actionWidth = helpPosition - 2 - 2;

    const lines = [this.formatUsage(), '\noptions:\n'];
    lines.push(
      `  ${'-h, --help'.padEnd(actionWidth, ' ')}  show this help message and exit\n`,
    );
    for (const action of this.actions) {
      lines.push(`  ${action.formatInvocation()}\n`);
    }
    return lines.join('');
  }

  /** argparse prints usage plus a one-line diagnostic, then exits with 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv) {
    const byFlag = new Map(this.actions.map((action) => [action.flag, action]));
    const values = new Map();
    const seen = new Set();
    const extras = [];
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (onlyPositionals) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        onlyPositionals = true;
        continue;
      }
      if (this.helpFlags.has(token)) {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      if (!looksLikeOptionString(token)) {
        extras.push(token);
        continue;
      }

      // `--flag=value` carries its own argument.
      const equals = token.indexOf('=');
      let flag = token;
      let inlineValue = null;
      if (equals !== -1) {
        flag = token.slice(0, equals);
        inlineValue = token.slice(equals + 1);
      }

      const action = byFlag.get(flag);
      if (action === undefined) {
        extras.push(token);
        continue;
      }

      let raw = inlineValue;
      if (raw === null) {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOptionString(next)) {
          this.error(`argument ${action.flag}: expected one argument`);
        }
        raw = next;
        i += 1;
      }

      // Later occurrences of the same flag overwrite earlier ones.
      values.set(action.dest, this.convert(action, raw));
      seen.add(action.dest);
    }

    // Missing required options are reported before unrecognized arguments.
    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.flag);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return Object.fromEntries(values);
  }

  convert(action, raw) {
    if (action.type !== 'int') return raw;
    const parsed = pyParseInt(raw);
    if (parsed === null) {
      this.error(`argument ${action.flag}: invalid int value: '${raw}'`);
    }
    return parsed;
  }
}

