  b58decode,
  b58decodeCheck,
  b58decodeInt,
  b58encode,
  b58encodeCheck,
  b58encodeInt,
} from './lib/base58.mjs';
import { utf8Encode } from './lib/bytes.mjs';
import { PyError, formatTraceback } from './lib/errors.mjs';
import { bytesRepr, intRepr } from './lib/pyrepr.mjs';

const parser = new ArgumentParser({ prog: basename(fileURLToPath(import.meta.url)) });
parser.addArgument('--a', { type: 'str', required: true });
parser.addArgument('--b', { type: 'str', required: true });
parser.addArgument('--c', { type: 'str', required: true });
parser.addArgument('--d', { type: 'str', required: true });
parser.addArgument('--e', { type: 'int', required: true });
parser.addArgument('--f', { type: 'int', required: true });
const args = parser.parseArgs(process.argv.slice(2));

