  console.log(bytesRepr(decodedD));
  console.log(bytesRepr(encodedIntE));
  console.log(bytesRepr(encodedIntF));
  console.log(intRepr(decodedIntE));
  console.log(bytesRepr(encodedCheckDecoded));
