#!/usr/bin/env node
/** Differential tester: /output/test19.mjs vs the precompiled Python executable. */
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test19_executable';
const JS = '/output/test19.mjs';

function run(cmd, argv) {
  const opts = { encoding: 'latin1', stdio: ['ignore', 'pipe', 'pipe'], timeout: 20000 };
  try {
    const out = cmd[0] === 'node'
      ? execFileSync('node', [JS, ...argv], opts)
      : execFileSync(EXE, argv, opts);
    return { code: 0, out };
  } catch (e) {
    return { code: e.status === null ? 'signal' : e.status, out: e.stdout ?? '' };
  }
}

const strPool = [
  '', ' ', '     ', '1', '11', '111', '1z', 'z', 'abc', 'ABC', '1234567890',
  'drn1vtp', 'U5Oa2ji3Q', 'TPcTsjvTNHtabUBA', '2Qu1ga2eTaoXNQzeniuzRQxH1rnQ',
  'c0C zQokldyRqDWOdqXxM2Eq4GyQ4sPmlsbgl', '中国汉字', 'héllo', 'ß',
  "it's", 'say "hi"', 'both \' and "', 'back\\slash', 'tab\there', 'nl\nhere',
  '\x01\x02\x7f', '0', 'O', 'I', 'l', '+/=', 'a b', ' 1', '1 ', '11  ',
  'ab\t', 'ab\n', '\r\n', '1'.repeat(40), 'Z'.repeat(60), '\x00',
  '😀', 'mixed 中 abc', '~!@#$%^&*()', 'aaaa    ',
];
// Strings that are valid base58 (safe for --b): decode must not raise.
const b58Pool = strPool.filter((s) => /^[123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz]*[ \t\n\r]*$/.test(s));
const intPool = ['0', '1', '9', '10', '57', '58', '59', '100', '255', '256',
  '473379435', '82019528', '99999999999999999999999999', '+7', '1_0', '  42  ',
  '0007', 'abc', '5.5', '', '1e3', '0x10', '١٢٣', '-0'];

const cases = [];
// Exhaustive-ish sweep over the interesting positions.
for (const s of strPool) {
  cases.push(['--a', s, '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
  cases.push(['--a', 'x', '--b', '1', '--c', s, '--d', 'z', '--e', '1', '--f', '2']);
  cases.push(['--a', 'x', '--b', '1', '--c', 'y', '--d', s, '--e', '1', '--f', '2']);
  cases.push(['--a', 'x', '--b', s, '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
}
for (const n of intPool) {
  cases.push(['--a', 'x', '--b', '1', '--c', 'y', '--d', 'z', '--e', n, '--f', '2']);
  cases.push(['--a', 'x', '--b', '1', '--c', 'y', '--d', 'z', '--e', '3', '--f', n]);
}
// Random combinations.
const rnd = (a) => a[Math.floor(Math.random() * a.length)];
for (let i = 0; i < 200; i++) {
  cases.push(['--a', rnd(strPool), '--b', rnd(b58Pool), '--c', rnd(strPool),
    '--d', rnd(strPool), '--e', rnd(intPool.slice(0, 14)), '--f', rnd(intPool.slice(0, 14))]);
}
// Argparse-shape cases.
cases.push([]);
cases.push(['--a', 'x']);
cases.push(['-h']);
cases.push(['--help']);
cases.push(['--a=hi', '--b=1', '--c=y', '--d=z', '--e=5', '--f=6']);
cases.push(['--a', 'x', '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2', '--g', 'q']);
cases.push(['foo', '--a', 'x', '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
cases.push(['--a', '--b', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
cases.push(['--a', 'x', '--a', 'yy', '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
cases.push(['--a', 'x', '--b', '1', '--c', 'y', '--d', 'z', '--e', '-5']); // missing --f
cases.push(['--a', '-1', '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
cases.push(['--a', '-x', '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2']);
cases.push(['--e', '1', '--f', '2', '--d', 'z', '--c', 'y', '--b', '1', '--a', 'x']);
cases.push(['--a', 'x', '--b', '1', '--c', 'y', '--d', 'z', '--e', '1', '--f', '2', '--']);

let pass = 0;
const fails = [];
for (const argv of cases) {
  const py = run(['exe'], argv);
  const js = run(['node'], argv);
  if (py.out === js.out && String(py.code) === String(js.code)) pass++;
  else fails.push({ argv, py, js });
}

console.log(`passed ${pass}/${cases.length}`);
for (const f of fails.slice(0, 25)) {
  console.log('\nARGV:', JSON.stringify(f.argv));
  console.log(` py(code=${f.py.code}):`, JSON.stringify(f.py.out));
  console.log(` js(code=${f.js.code}):`, JSON.stringify(f.js.out));
}
process.exit(fails.length ? 1 : 0);

