/**
 * `repr(str)` for the single characters base58 names in its error messages.
 * Follows the same quote-selection rule as `bytesRepr`.
 */
export function charRepr(codePoint) {
  const quote = codePoint === QUOTE_SINGLE ? QUOTE_DOUBLE : QUOTE_SINGLE;
  const delimiter = String.fromCharCode(quote);

  let body;
  if (codePoint === quote || codePoint === BACKSLASH) {
    body = '\\' + String.fromCharCode(codePoint);
  } else if (codePoint === 0x09) body = '\\t';
  else if (codePoint === 0x0a) body = '\\n';
  else if (codePoint === 0x0d) body = '\\r';
  else if (codePoint < 0x20 || codePoint === 0x7f) {
    body = '\\x' + codePoint.toString(16).padStart(2, '0');
  } else body = String.fromCharCode(codePoint);

  return `${delimiter}${body}${delimiter}`;
}

