/**
 * Categories for which `str.isprintable()` is false, and which `repr(str)`
 * therefore escapes.  Space is the one Zs character Python keeps literal.
 */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(char) {
  return char === ' ' || !NON_PRINTABLE.test(char);
}

/**
 * `repr(str)`.
 *
 * Same quote-selection rule as `bytesRepr`, but escaping is driven by Unicode
 * printability and widens to `\uXXXX` / `\UXXXXXXXX` above the Latin-1 range.
 */
export function strRepr(text) {
  let singles = 0;
  let doubles = 0;
  for (const char of text) {
    if (char === "'") singles += 1;
    else if (char === '"') doubles += 1;
  }

  const delimiter = singles > 0 && doubles === 0 ? '"' : "'";

  let body = '';
  for (const char of text) {
    const cp = char.codePointAt(0);
    if (char === delimiter || cp === BACKSLASH) body += '\\' + char;
    else if (cp === 0x09) body += '\\t';
    else if (cp === 0x0a) body += '\\n';
    else if (cp === 0x0d) body += '\\r';
    else if (!isPrintable(char)) {
      if (cp <= 0xff) body += '\\x' + cp.toString(16).padStart(2, '0');
      else if (cp <= 0xffff) body += '\\u' + cp.toString(16).padStart(4, '0');
      else body += '\\U' + cp.toString(16).padStart(8, '0');
    } else body += char;
  }

  return `${delimiter}${body}${delimiter}`;
}

/** `repr(chr(byte))` for the single characters base58 names in its errors. */
export function charRepr(codePoint) {
  return strRepr(String.fromCodePoint(codePoint));
}

