/**
 * CPython `repr()` reproduction for the values this script prints.
 *
 * `print(some_bytes)` emits `repr(some_bytes)`, so the `b'...'` wrapper, the
 * quote-character choice and the escape rules all have to be reproduced exactly.
 */

const QUOTE_SINGLE = 0x27;
const QUOTE_DOUBLE = 0x22;
const BACKSLASH = 0x5c;

/**
 * `repr(bytes)`.
 *
 * CPython counts the quote characters first: a value containing `'` but no `"`
 * is delimited with `"` so the apostrophes can stay bare.  Otherwise `'`
 * delimits and any embedded apostrophe is backslash-escaped.
 */
export function bytesRepr(bytes) {
  let singles = 0;
  let doubles = 0;
  for (const byte of bytes) {
    if (byte === QUOTE_SINGLE) singles += 1;
    else if (byte === QUOTE_DOUBLE) doubles += 1;
  }

  const quote = singles > 0 && doubles === 0 ? QUOTE_DOUBLE : QUOTE_SINGLE;
  const delimiter = String.fromCharCode(quote);

  let body = '';
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) body += '\\' + String.fromCharCode(byte);
    else if (byte === 0x09) body += '\\t';
    else if (byte === 0x0a) body += '\\n';
    else if (byte === 0x0d) body += '\\r';
    else if (byte < 0x20 || byte >= 0x7f) body += '\\x' + byte.toString(16).padStart(2, '0');
