/** `str.encode()` — the UTF-8 default codec. */
export function utf8Encode(text) {
  const out = [];
  for (const { cp, index } of codePoints(text)) {
    if (cp >= 0xd800 && cp <= 0xdfff) {
      throw new PyUnicodeEncodeError(
        `'utf-8' codec can't encode character '${codePointName(cp)}' in position ` +
          `${index}: surrogates not allowed`,
      );
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/** `str.encode('ascii')` — used by base58's input scrubber. */
export function asciiEncode(text) {
  const out = [];
  for (const { cp, index } of codePoints(text)) {
    if (cp > 0x7f) {
      throw new PyUnicodeEncodeError(
        `'ascii' codec can't encode character '${codePointName(cp)}' in position ` +
          `${index}: ordinal not in range(128)`,
      );
    }
    out.push(cp);
  }
  return out;
}

