/**
 * Build a codec error message the way CPython does: the offending run of
 * characters is reported as a whole.  A single character is named and escaped,
 * a longer run is reported only as a position range.
 */
function codecError(codec, points, start, isBad, reason) {
  let end = start;
  while (end < points.length && isBad(points[end].cp)) end += 1;

  const where =
    end - start === 1
      ? `character '${codePointName(points[start].cp)}' in position ${start}`
      : `characters in position ${start}-${end - 1}`;
  return `'${codec}' codec can't encode ${where}: ${reason}`;
}

/** `str.encode()` — the UTF-8 default codec. */
export function utf8Encode(text) {
  const points = codePoints(text);
  const isSurrogate = (cp) => cp >= 0xd800 && cp <= 0xdfff;

  const out = [];
  for (let i = 0; i < points.length; i += 1) {
    const cp = points[i].cp;
    if (isSurrogate(cp)) {
      throw new PyUnicodeEncodeError(
        codecError('utf-8', points, i, isSurrogate, 'surrogates not allowed'),
      );
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/** `str.encode('ascii')` — used by base58's input scrubber. */
export function asciiEncode(text) {
